DROP TABLE IF EXISTS `sys_account`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `sys_account` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `username` varchar(50) NOT NULL COMMENT '登录账号 (厂家分配)',
  `password` varchar(64) NOT NULL COMMENT '密码值',
  `shop_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '所属门店/客户名称 (方便后台对账管理)',
  `expire_time` datetime NOT NULL COMMENT '账号授权到期时间 (到期自动拒绝登录)',
  `status` tinyint(1) NOT NULL DEFAULT '1' COMMENT '状态: 1=正常, 0=封禁/停用',
  `current_mac` varchar(50) DEFAULT NULL COMMENT '当前登录设备的MAC地址 (用于顶号或设备绑定)',
  `last_login_time` datetime DEFAULT NULL COMMENT '最后活跃时间 (结合心跳包更新)',
  `last_heartbeat_time` datetime DEFAULT NULL COMMENT '最后一次有效心跳时间',
  `user_permissions` tinyint NOT NULL DEFAULT '0' COMMENT '权限级别: 0=普通客户端, 1=超级管理员',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_username` (`username`)
) ENGINE=InnoDB AUTO_INCREMENT=10004 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='中控主机授权账号表';
/*!40101 SET character_set_client = @saved_cs_client */;

