DROP TABLE IF EXISTS `t_client_version`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `t_client_version` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `version` varchar(32) NOT NULL COMMENT '版本号，如 1.0.0',
  `version_code` int NOT NULL DEFAULT '0' COMMENT '版本序号，用于数值比较，越大越新',
  `exe_path` varchar(500) NOT NULL DEFAULT './UploadedAssets/Client/DemandStation.exe' COMMENT '服务端 exe 文件路径',
  `file_md5` varchar(64) NOT NULL DEFAULT '' COMMENT 'exe 文件 MD5',
  `file_size` bigint NOT NULL DEFAULT '0' COMMENT 'exe 文件大小(字节)',
  `update_flag` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否有更新: 0=无, 1=有',
  `force_update` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否强制更新: 0=否, 1=是',
  `release_notes` text COMMENT '更新日志',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='客户端版本管理表';
