--
-- Table structure for table `t_user_devicelist`
--

DROP TABLE IF EXISTS `t_user_devicelist`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `t_user_devicelist` (
  `DeviceID` varchar(128) NOT NULL COMMENT '设备唯一标识符 (MAC或SN码)',
  `User_Id` int NOT NULL COMMENT '所属用户的ID (关联 sys_account.id)',
  `DeviceNick` varchar(100) DEFAULT NULL COMMENT '设备自定义昵称',
  `team_name` varchar(50) DEFAULT NULL COMMENT '队伍名称 (如 Red, Blue)',
  `play_time` varchar(50) DEFAULT NULL COMMENT '游玩时间/目标时间',
  PRIMARY KEY (`DeviceID`),
  KEY `idx_user_id` (`User_Id`),
  CONSTRAINT `fk_devicelist_user` FOREIGN KEY (`User_Id`) REFERENCES `sys_account` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='VR设备列表与持久化状态表';
/*!40101 SET character_set_client = @saved_cs_client */;

