DROP TABLE IF EXISTS `t_user_game_rel`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `t_user_game_rel` (
  `user_id` int NOT NULL COMMENT '用户ID (关联 sys_account.id)',
  `game_name` varchar(50) NOT NULL COMMENT '游戏名称 (PVP / MiniWorld)',
  `device_count` int NOT NULL DEFAULT '0' COMMENT '该游戏授权支持的最大设备数量',
  `points_per_session` int NOT NULL DEFAULT '0' COMMENT '每次启动游戏消耗的积分数',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '授权时间',
  PRIMARY KEY (`user_id`,`game_name`),
  CONSTRAINT `fk_user_game_rel_user` FOREIGN KEY (`user_id`) REFERENCES `sys_account` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='用户游戏授权关联表';
